// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { 
        vm.deal(address(this), 10 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}(); 
    }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 2 ether);
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(0x1234)));

        vm.roll(block.number + 2);
        vm.warp(block.timestamp + 14);

        uint256 balanceBefore = user.balance;
        vm.prank(user);
        c.settle();
        uint256 balanceAfter = user.balance;

        assertTrue(balanceAfter == balanceBefore);
    }
}
